import { html } from '../../../@microsoft/fast-element/dist/esm/index.js';

function windowPanelTemplate() {
    return html `
		<template
			slot="tabpanel"
			role="region"
			?is-full-width="${(x) => (x.isFullWidth ? x.isFullWidth : void 0)}"
		>
			<slot></slot>
		</template>
	`;
}

export { windowPanelTemplate };
